function parseFtp(url){
  url=(url||'').trim();
  if(!url) return {valid:false,error:'空输入'};
  var m=url.match(/^([a-zA-Z]+):\/\/(.*)$/);
  if(!m) return {valid:false,error:'缺少 scheme://（支持 ftp/ftps/sftp）'};
  var scheme=m[1].toLowerCase(), rest=m[2];
  var defs={ftp:21,ftps:990,sftp:22};
  if(!(scheme in defs)) return {valid:false,error:'不支持的 scheme: '+scheme};
  var auth='', path=rest;
  var at=rest.indexOf('@');
  if(at>=0){ auth=rest.slice(0,at); path=rest.slice(at+1); }
  var user='', pass='';
  if(auth){ var c=auth.indexOf(':'); if(c>=0){ user=auth.slice(0,c); pass=auth.slice(c+1);} else user=auth; }
  var q='', hp=path;
  var qi=path.indexOf('?');
  if(qi>=0){ hp=path.slice(0,qi); q=path.slice(qi+1); }
  var slash=hp.indexOf('/');
  var hostport= slash>=0 ? hp.slice(0,slash) : hp;
  var fpath= slash>=0 ? hp.slice(slash) : '/';
  var port=defs[scheme], host=hostport;
  var colon=hostport.lastIndexOf(':');
  if(colon>=0 && hostport[colon+1]!=='/'){
    var p=parseInt(hostport.slice(colon+1),10);
    if(!isNaN(p)&&p>=0&&p<=65535){ host=hostport.slice(0,colon); port=p; }
  }
  return {valid:true, scheme:scheme, host:host, port:port, user:user, password:pass, path:fpath, query:q};
}

var EXPORTS={parseFtp:parseFtp};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.FtpForgePure = EXPORTS; }
